    /// <summary>Bachata (<c>BAC</c>) — Dominican guitar-based dance music descended from bolero and son, defined by a lead requinto guitar playing high, arpeggiated melodic licks over rhythm guitar, bass, bongó and the scraping güira; long stigmatized as "música de amargue" before Juan Luis Guerra and later Aventura/Romeo Santos carried it worldwide.</summary>
    public static readonly Genre Bachata = new(new GenreCode("BAC"), "Bachata", ["Bachata Dominicana"], "Dominican guitar-based dance music descended from bolero and son, defined by a lead requinto guitar playing high, arpeggiated melodic licks over rhythm guitar, bass, bongó and the scraping güira; long stigmatized as \"música de amargue\" before Juan Luis Guerra and later Aventura/Romeo Santos carried it worldwide. Its four-beat cycle ends on a syncopated hip-accent (\"pop\") on the fourth count that the partner dance mirrors with a tap. A core street-latin social-floor genre, often shared on salsa social floors and ranging from traditional acoustic to modern sensual and urban bachata. Distinguishing trait: vs Salsa requinto-guitar lead and a closed four-count tap-on-four step, where Salsa is horn-and-piano (montuno) driven and locked to the eight-count clave.") { Family = "latin", EraStart = 1960, DanceRelevance = DanceRelevance.High, BpmRange = new BpmRange(108, 152), Source = "SDTS scene-completeness rework (2026-06): the dance-scene genre its scene's dances are danced to, absent from the swing/blues-seeded catalog. Researched + adversarially verified via multi-agent workflow." };
    /// <summary>Bolero (<c>BOL</c>) — A slow, romantic Latin-American ballad born in late-19th-century Santiago de Cuba and spread across the Hispanic world by the guitar trios romanticos and orchestral crooners.</summary>
    public static readonly Genre Bolero = new(new GenreCode("BOL"), "Bolero", ["Bolero Cubano", "Cuban Bolero", "Bolero Romántico"], "A slow, romantic Latin-American ballad born in late-19th-century Santiago de Cuba and spread across the Hispanic world by the guitar trios romanticos and orchestral crooners. Set in 4/4 over a syncopated cinquillo-derived pulse, it foregrounds a lush, sentimental melody and lyrics of love and longing, sung over guitars or a string-and-rhythm orchestra at a languid tempo. As a slow Cuban partner-dance music it underlies the bolero social dance and the codified International and American ballroom Rumba. Distinguishing trait: vs Son Cubano, Bolero is the slow, legato, melody-and-lyric romantic ballad, where Son Cubano is up-tempo dance music driven by the son clave, an anticipated tumbao bass and a call-and-response montuno.") { Family = "latin", EraStart = 1885, DanceRelevance = DanceRelevance.High, BpmRange = new BpmRange(80, 130), Source = "SDTS scene-completeness rework (2026-06): the dance-scene genre its scene's dances are danced to, absent from the swing/blues-seeded catalog. Researched + adversarially verified via multi-agent workflow." };
    /// <summary>Cha-Cha-Chá (<c>CHA</c>) — A Cuban dance-music genre created by violinist Enrique Jorrín around 1953 as a slower, squarer offshoot of danzón-mambo, played by charanga ensembles (flute, strings, piano, güiro, timbales).</summary>
    public static readonly Genre ChaChaCha = new(new GenreCode("CHA"), "Cha-Cha-Chá", ["Cha-Cha", "Cha Cha", "Chachachá", "ChaChaCha"], "A Cuban dance-music genre created by violinist Enrique Jorrín around 1953 as a slower, squarer offshoot of danzón-mambo, played by charanga ensembles (flute, strings, piano, güiro, timbales). Its onomatopoeic name comes from the shuffled triple-step the dancers land on the 4-and-1, marked by the güiro and a strong on-beat pulse. It anchors social Cuban/casino floors and is also a codified International Latin ballroom dance. Distinguishing trait: vs Mambo it is slower, simpler and more on-the-beat with a charanga flute-and-strings sound rather than the faster brass-driven big-band attack, and its signature triple-step replaces mambo's break-step.") { Family = "latin", EraStart = 1953, DanceRelevance = DanceRelevance.High, BpmRange = new BpmRange(100, 135), Source = "SDTS scene-completeness rework (2026-06): the dance-scene genre its scene's dances are danced to, absent from the swing/blues-seeded catalog. Researched + adversarially verified via multi-agent workflow." };
    /// <summary>Kizomba (<c>KIZ</c>) — An Angolan popular genre that emerged in the early 1980s, blending the local semba tradition with the smooth electronic production and rhythm of French-Caribbean zouk, sung mostly in Portuguese.</summary>
    public static readonly Genre Kizomba = new(new GenreCode("KIZ"), "Kizomba", [], "An Angolan popular genre that emerged in the early 1980s, blending the local semba tradition with the smooth electronic production and rhythm of French-Caribbean zouk, sung mostly in Portuguese. It rides a slow, grounded 4/4 around 80-110 BPM with a soft, romantic groove built for the close-embrace partner dance of the same name. Its steady, unhurried pulse and warm synth-and-bass texture make it a central pillar of the street-latin social floor. Distinguishing trait: vs Zouk it keeps a slower, more grounded steady African pulse rooted in semba, where Brazilian zouk runs faster with a syncopated lambada-derived sway.") { Family = "world", EraStart = 1984, DanceRelevance = DanceRelevance.High, BpmRange = new BpmRange(80, 110), Source = "SDTS scene-completeness rework (2026-06): the dance-scene genre its scene's dances are danced to, absent from the swing/blues-seeded catalog. Researched + adversarially verified via multi-agent workflow." };
    /// <summary>Mambo (<c>MAM</c>) — Fast, brass-driven Cuban big-band dance music that grew out of the danzón-mambo of the late 1930s and exploded into the orchestral mambo craze of the late 1940s-50s (Pérez Prado, and the New York Afro-Cuban bands of Machito and Tito Puente).</summary>
    public static readonly Genre Mambo = new(new GenreCode("MAM"), "Mambo", ["Mambo Cubano", "Big-Band Mambo"], "Fast, brass-driven Cuban big-band dance music that grew out of the danzón-mambo of the late 1930s and exploded into the orchestral mambo craze of the late 1940s-50s (Pérez Prado, and the New York Afro-Cuban bands of Machito and Tito Puente). It locks a horn-section riff and montuno piano vamp over the clave and a tumbao bass, with punchy syncopated brass accents and call-and-response between sections driving the floor. As the dance that established the \"on 2\" break-step timing, it is the direct forerunner of New York salsa and a foundational genre of the mambo/salsa floor. Distinguishing trait: vs Salsa it is the older big-band ancestor, brassier and more orchestral with longer instrumental riff sections, where Salsa is its tighter, song-driven 1970s codification.") { Family = "latin", EraStart = 1940, DanceRelevance = DanceRelevance.High, BpmRange = new BpmRange(160, 200), Source = "SDTS scene-completeness rework (2026-06): the dance-scene genre its scene's dances are danced to, absent from the swing/blues-seeded catalog. Researched + adversarially verified via multi-agent workflow." };
