    public static readonly Genre Merengue = new(new GenreCode("MER"), "Merengue", ["Merengue Típico", "Perico Ripiao", "Merengue Dominicano"], "The national dance music of the Dominican Republic — a fast, driving 2/4 march built on the tambora drum and the scraping güira, originally accordion-led (perico ripiao) and later expanded into horn-driven orquesta and big-band merengue. It carries an even, relentless two-step pulse with marcado bass and saxophone jaleo riffs, made for the simplest and most accessible of the Latin social dances. A floor staple across street-latin nights, played in sets alongside salsa and bachata. Distinguishing trait: vs Bachata it is a fast 2/4 march on tambora and güira rather than a slower 4/4 ballad led by the requinto guitar.") { Family = "latin", EraStart = 1850, DanceRelevance = DanceRelevance.High, BpmRange = new BpmRange(120, 170), Source = "SDTS scene-completeness rework (2026-06): the dance-scene genre its scene's dances are danced to, absent from the swing/blues-seeded catalog. Researched + adversarially verified via multi-agent workflow." };
    /// <summary>Milonga (<c>MLG</c>) — The fast, playful member of the Rioplatense tango family, built on the syncopated habanera bass cell in a brisk 2/4 — earthier and more rhythmic than tango, with a teasing, ground-hugging bounce (Sebastián Piana, Francisco Canaro, Aníbal Troilo).</summary>
    public static readonly Genre Milonga = new(new GenreCode("MLG"), "Milonga", ["Milonga Porteña", "Milonga Ciudadana", "Milonga Argentina"], "The fast, playful member of the Rioplatense tango family, built on the syncopated habanera bass cell in a brisk 2/4 — earthier and more rhythmic than tango, with a teasing, ground-hugging bounce (Sebastián Piana, Francisco Canaro, Aníbal Troilo). Its double-time subdivision invites the traspié contratiempo double-steps that define the dance, and it shares the Golden-Age orquesta sound and quarter-note tempo range with its tango sibling. Note: \"milonga\" also names the tango social event itself; here it denotes the music/dance genre. Distinguishing trait: vs Tango it rides the habanera double-time 2/4 cell with a light, bouncing swing rather than the grounded marcato 4/4 walking pulse.") { Parent = "tango", Family = "regional", EraStart = 1930, DanceRelevance = DanceRelevance.High, BpmRange = new BpmRange(110, 138), Source = "SDTS scene-completeness rework (2026-06): the dance-scene genre its scene's dances are danced to, absent from the swing/blues-seeded catalog. Researched + adversarially verified via multi-agent workflow." };
    /// <summary>Paso Doble (<c>PSD</c>) — A dramatic Spanish two-step march in brisk 2/4, rooted in military and bullfight band music and evoking the matador's cape-and-charge in the arena (the near-universal competition tune is "España Cañí").</summary>
    public static readonly Genre PasoDoble = new(new GenreCode("PSD"), "Paso Doble", ["Pasodoble", "Paso", "España Cañí"], "A dramatic Spanish two-step march in brisk 2/4, rooted in military and bullfight band music and evoking the matador's cape-and-charge in the arena (the near-universal competition tune is \"España Cañí\"). Built on a steady on-beat march cadence with flamenco-tinged melodies, brass fanfares, and theatrical accents and halts that cue the dancers' poses. Distinguishing trait: vs Tango it is a straight on-beat Spanish march built around dramatic halts, not a marcato-pulse bandoneon embrace.") { Family = "regional", EraStart = 1920, DanceRelevance = DanceRelevance.High, BpmRange = new BpmRange(112, 138), Source = "SDTS scene-completeness rework (2026-06): the dance-scene genre its scene's dances are danced to, absent from the swing/blues-seeded catalog. Researched + adversarially verified via multi-agent workflow." };
    /// <summary>Rumba (Cuban) (<c>RMB</c>) — Secular Afro-Cuban folkloric music from the dockside solares of Havana and Matanzas, built entirely on layered congas/cajón, claves, palitos and call-and-response vocals with no melodic instruments.</summary>
    public static readonly Genre RumbaCubana = new(new GenreCode("RMB"), "Rumba (Cuban)", ["Rumba Cubana", "Cuban Rumba", "Guaguancó", "Yambú", "Columbia", "Rumba Guaguancó"], "Secular Afro-Cuban folkloric music from the dockside solares of Havana and Matanzas, built entirely on layered congas/cajón, claves, palitos and call-and-response vocals with no melodic instruments. Its three sub-forms drive distinct dances: the flirtatious couple guaguancó, the slow elder yambú, and the acrobatic solo male columbia. Danced socially in rumba gatherings and as the percussive root feeding casino/Afro-Cuban movement. Distinguishing trait: vs Son the rumba is pure percussion and voice over a 2-bar rumba clave with no melodic instruments, where the son adds tres/guitar, bass and a sung melody.") { Family = "latin", EraStart = 1880, DanceRelevance = DanceRelevance.Medium, BpmRange = new BpmRange(90, 130), Source = "SDTS scene-completeness rework (2026-06): the dance-scene genre its scene's dances are danced to, absent from the swing/blues-seeded catalog. Researched + adversarially verified via multi-agent workflow." };
    /// <summary>Samba (Music) (<c>SMB</c>) — Brazil's signature Afro-Brazilian dance music, born in early-20th-century Rio de Janeiro and inseparable from Carnival, built on a fast 2/4 pulse driven by a surdo-and-tamborim percussion battery with a strong "two" and busy sixteenth-note syncopation.</summary>
    public static readonly Genre Samba = new(new GenreCode("SMB"), "Samba (Music)", ["Samba no Pé", "Brazilian Samba"], "Brazil's signature Afro-Brazilian dance music, born in early-20th-century Rio de Janeiro and inseparable from Carnival, built on a fast 2/4 pulse driven by a surdo-and-tamborim percussion battery with a strong \"two\" and busy sixteenth-note syncopation. The buoyant, bouncing groove carries social samba no pé and partnered samba de gafieira on the street-latin floor and underpins the codified International Latin ballroom samba. Vocal and pandeiro-led variants (pagode, partido alto) and the percussion-only batucada all share its swinging, springy momentum. Distinguishing trait: vs Bossa Nova it is a fast, full-throttle percussion-driven dance groove rather than bossa's hushed, slow whispered-guitar comp drawn from the same samba root.") { Family = "latin", EraStart = 1916, DanceRelevance = DanceRelevance.High, BpmRange = new BpmRange(96, 120), Source = "SDTS scene-completeness rework (2026-06): the dance-scene genre its scene's dances are danced to, absent from the swing/blues-seeded catalog. Researched + adversarially verified via multi-agent workflow." };
    /// <summary>Son Cubano (<c>SON</c>) — The foundational Afro-Cuban genre from eastern Cuba's Oriente, built on the son clave, the tres guitar's syncopated guajeo, and a two-part form that opens with a sung verse and breaks into an open call-and-response montuno over anticipated tumbao bass and bongó/clave percussion (Trío Matamoros, Sexteto Habanero, Arsenio Rodríguez, later Buena Vista Social Club).</summary>
    public static readonly Genre SonCubano = new(new GenreCode("SON"), "Son Cubano", ["Cuban Son", "Son Montuno"], "The foundational Afro-Cuban genre from eastern Cuba's Oriente, built on the son clave, the tres guitar's syncopated guajeo, and a two-part form that opens with a sung verse and breaks into an open call-and-response montuno over anticipated tumbao bass and bongó/clave percussion (Trío Matamoros, Sexteto Habanero, Arsenio Rodríguez, later Buena Vista Social Club). It is the trunk from which mambo, cha-cha-chá, and salsa all grew, and it remains a living social-floor music in the casino/salsa world, danced grounded on the contratiempo. Distinguishing trait: vs Salsa, son is the slower, sparser, tres-led acoustic root, where salsa is its faster, brighter, horn-section-driven New York codification of the same clave-and-montuno lineage.") { Family = "latin", EraStart = 1900, DanceRelevance = DanceRelevance.High, BpmRange = new BpmRange(140, 180), Source = "SDTS scene-completeness rework (2026-06): the dance-scene genre its scene's dances are danced to, absent from the swing/blues-seeded catalog. Researched + adversarially verified via multi-agent workflow." };
    /// <summary>Vals (<c>VLS</c>) — The Rioplatense tango waltz — a 3/4 tango-family form (vals criollo) played by the same Golden-Age orquestas as tango and milonga, with a continuously flowing, circular lilt felt one-per-bar over a strong beat 1.</summary>
    public static readonly Genre Vals = new(new GenreCode("VLS"), "Vals", ["Tango Vals", "Tango Waltz", "Vals Criollo", "Vals Cruzado"], "The Rioplatense tango waltz — a 3/4 tango-family form (vals criollo) played by the same Golden-Age orquestas as tango and milonga, with a continuously flowing, circular lilt felt one-per-bar over a strong beat 1. It is one of the three core tanda types spun at every milonga, ranging from lyrical Fresedo/De Angelis valses to fast, driving D'Arienzo/Biagi readings. Dancers cross-step and turn on the accented beats, gliding around the bar rather than marking each beat. Distinguishing trait: vs Tango it is in 3/4 felt one-per-bar with a rotary, sweeping flow, where tango is a marcato 4/4 with sharp staccato accents and walked steps.") { Parent = "tango", Family = "regional", EraStart = 1900, DanceRelevance = DanceRelevance.High, BpmRange = new BpmRange(150, 240), Source = "SDTS scene-completeness rework (2026-06): the dance-scene genre its scene's dances are danced to, absent from the swing/blues-seeded catalog. Researched + adversarially verified via multi-agent workflow." };
    /// <summary>Brazilian Zouk (<c>ZOU</c>) — The music of the Brazilian Zouk floor: a slow, syncopated 4/4 in the zouk lineage, descended from the Antillean zouk of Kassav' and Cape-Verdean coladeira and reshaped through Brazilian lambada into the body-wave "tum-tum-tchi" groove dancers ride today.</summary>
    public static readonly Genre Zouk = new(new GenreCode("ZOU"), "Brazilian Zouk", ["Zouk", "Lambada-Zouk", "Zouk-Lambada"], "The music of the Brazilian Zouk floor: a slow, syncopated 4/4 in the zouk lineage, descended from the Antillean zouk of Kassav' and Cape-Verdean coladeira and reshaped through Brazilian lambada into the body-wave \"tum-tum-tchi\" groove dancers ride today. Its half-time backbeat and floating, melodic phrasing invite long flowing body movement, head rolls and elastic lead-follow connection rather than quick footwork, and modern floors stretch it across zouk-pop and slowed-down R&B and pop remixes at the same tempo. Distinguishing trait: vs Kizomba it is lambada-derived with a syncopated, count-and-a body-wave groove and floating melodic phrasing, where Kizomba is Angolan semba-derived with a grounded, steady African pulse.") { Family = "world", EraStart = 1980, DanceRelevance = DanceRelevance.High, BpmRange = new BpmRange(100, 130), Source = "SDTS scene-completeness rework (2026-06): the dance-scene genre its scene's dances are danced to, absent from the swing/blues-seeded catalog. Researched + adversarially verified via multi-agent workflow." };

