    /// <summary>Project a runtime term (e.g. a custom/overlay term absent from this baseline
    /// catalog) to a Genre. Used by the typed view when ById has no entry.</summary>
    public static Genre FromTerm(VocabularyTerm t) =>
        new(new GenreCode(t.Display?.Code ?? ""), t.Canonical, t.Aliases, "");
}

/// <summary>A parsed genre occurrence: a catalog <see cref="Genre"/> (or <see cref="Genres.Generic"/>) plus the exact text it was
/// read from, tagged with how it entered the field. Its own type so a GenreValue can't be used
/// where another dimension's value is expected (CLAUDE.md guideline 1).</summary>
public readonly record struct GenreValue(Genre Term, string StoredValue, ValueOrigin Origin = ValueOrigin.Stored)
{
    /// <summary>False when the value did not match the catalog (Term == Genres.Generic).</summary>
    public bool IsKnown => !ReferenceEquals(Term, Genres.Generic);
    /// <summary>The catalog form; equals StoredValue for an unknown (Generic has no canonical).</summary>
    public string Canonical => IsKnown ? Term.Canonical : StoredValue;
}

/// <summary>A genre field reading: the parsed values plus the exact original frame string
/// (preserved for byte-for-byte write-back).</summary>
public sealed record GenreField(IReadOnlyList<GenreValue> Values, string RawFrame);

/// <summary>Typed resolver for the genre dimension over a loaded (possibly customized)
/// vocabulary — the matching engine stays Dimension.Resolve; this is a thin typed projection.</summary>
public sealed class GenreView
{
    private readonly Dimension _dim;
    private readonly string _delimiter;

    /// <summary>Wrap a runtime dimension; <paramref name="delimiter"/> is the multi-value separator.</summary>
    public GenreView(Dimension dimension, string delimiter = "; ")
    {
        _dim = dimension;
        _delimiter = string.IsNullOrEmpty(delimiter) ? "; " : delimiter;
    }

    /// <summary>The generic (not-in-catalog) genre term.</summary>
    public Genre Generic => Genres.Generic;

    /// <summary>Resolve one token; a miss returns the generic carrying the raw text. Never null.</summary>
    public GenreValue Resolve(string token)
    {
        var term = _dim.Resolve(token);
        if (term is null) return new GenreValue(Genres.Generic, token);
        var hit = Genres.ById.TryGetValue(term.Id, out var c) ? c : Genres.FromTerm(term);
        return new GenreValue(hit, token);
    }

    /// <summary>Read a whole (multi-value) frame: per-value occurrences + the exact original frame.</summary>
    public GenreField Read(string? rawFrame)
    {
        var frame = rawFrame ?? "";
        var values = new List<GenreValue>();
        foreach (var part in frame.Split([_delimiter], System.StringSplitOptions.None))
        {
            var token = part.Trim();
            if (token.Length == 0) continue;
            values.Add(Resolve(token));
        }
        return new GenreField(values, frame);
    }
}

